107	    private static void insert(int[] values, int fromIndex, int index) {
108	        int value = values[index];
109	        int position = index - 1;
110	
111	        while (position >= fromIndex && values[position] > value) {
112	            values[position + 1] = values[position];
113	            position--;
114	        }
115	
116	        values[position + 1] = value;
117	    }
