179	    private static void sortRange(Range range, InsertionStep insertionStep) {
180	        if (range.isTrivial()) {
181	            return;
182	        }
183	
184	        for (int index = range.fromIndex + 1; index < range.toIndex; index++) {
185	            insertionStep.insert(range.fromIndex, index);
186	        }
