189	    private static boolean isSorted(Range range, OutOfOrderPredicate outOfOrderPredicate) {
190	        for (int index = range.fromIndex + 1; index < range.toIndex; index++) {
191	            if (outOfOrderPredicate.test(index - 1, index)) {
192	                return false;
193	            }
194	        }
195	
196	        return true;
197	    }
